toolScript:
// Game State
        let currentLevel = 1;
        let misclicks = 0;
        const container = document.getElementById('level-container');
        const indicator = document.getElementById('level-indicator');
        function startGame() {
            document.getElementById('start-screen').classList.add('hidden');
            container.classList.remove('hidden');
            loadLevel(1);
        }
        function fail(msg) {
            misclicks++;
            // Visual Shake on Main Container
            const arena = document.getElementById('game-arena');
            const shakeEl = container.firstElementChild || container;
            shakeEl.classList.remove('shake-element');
            void shakeEl.offsetWidth; // Trigger reflow
            shakeEl.classList.add('shake-element');
            // Toast Notification inside Game Area
            const toast = document.createElement('div');
            toast.className = "absolute top-4 left-1/2 -translate-x-1/2 bg-red-500 text-white px-6 py-2 rounded-full text-xs font-black uppercase tracking-widest shadow-xl z-50 pointer-events-none transition-opacity duration-500";
            toast.innerText = msg || "Dark Pattern Trap!";
            arena.appendChild(toast);
            setTimeout(() => {
                toast.style.opacity = '0';
                setTimeout(() => toast.remove(), 500);
            }, 1000);
        }
        function success() {
            currentLevel++;
            if (currentLevel > 5) {
                showVictory();
            } else {
                // Small delay for effect
                setTimeout(() => loadLevel(currentLevel), 200);
            }
        }
        function showVictory() {
            container.innerHTML = '';
            container.classList.add('hidden');
            document.getElementById('victory-screen').classList.remove('hidden');
            document.getElementById('final-score').innerText = misclicks;
            document.getElementById('level-indicator').innerText = "5";
        }
        function loadLevel(level) {
            indicator.innerText = level;
            container.innerHTML = '';
            // --- LEVEL 1: Visual Hierarchy (Confirmshaming) ---
            if (level === 1) {
                container.innerHTML = `
                    <div class="bg-white p-8 rounded-2xl modal-shadow text-center">
                        <h3 class="text-xl font-bold text-slate-800 mb-2">Manage Subscription</h3>
                        <p class="text-slate-500 mb-8 text-sm">We're sad to see you go. Are you sure?</p>
                        <div class="flex flex-col gap-3">
                            <button onclick="fail('You stayed subscribed!')" class="btn-primary w-full py-4 rounded-xl text-white font-bold shadow-md hover:scale-[1.02] transition-transform">
                                Keep My Benefits & Stay Subscribed
                            </button>
                            <button onclick="success()" class="text-xs text-slate-300 hover:text-slate-500 hover:underline py-2 mt-2">
                                No thanks, I hate saving money and love ads
                            </button>
                        </div>
                    </div>
                `;
            }
            // --- LEVEL 2: The Runaway Button (Fitts's Law violation) ---
            else if (level === 2) {
                container.innerHTML = `
                    <div class="bg-white p-8 rounded-2xl modal-shadow text-center relative h-80 flex flex-col items-center justify-center overflow-hidden">
                        <div class="absolute top-4 right-4 text-xs text-slate-300 font-mono">ADVERTISEMENT</div>
                        <h3 class="text-xl font-bold text-slate-800 mb-2">Wait! One last offer.</h3>
                        <p class="text-slate-500 mb-6 text-sm">Get 50% off for 0 months?</p>
                        <button onclick="fail('Accepted offer!')" class="btn-primary px-10 py-4 rounded-xl text-white font-bold shadow-md mb-4 z-10 w-3/4">
                            Claim Offer
                        </button>
                        <button id="runaway-btn" class="btn-trick px-4 py-2 rounded-lg text-xs bg-slate-100 hover:bg-slate-200 border border-slate-300 absolute bottom-6 transition-all duration-100 ease-out">
                            Reject Offer
                        </button>
                    </div>
                `;
                setTimeout(() => {
                    const btn = document.getElementById('runaway-btn');
                    // Mouseover logic for desktop
                    btn.addEventListener('mouseenter', () => {
                        const parent = btn.parentElement;
                        const maxX = parent.clientWidth - btn.clientWidth - 20;
                        const maxY = parent.clientHeight - btn.clientHeight - 20;
                        const newX = Math.random() * maxX;
                        const newY = Math.random() * maxY;
                        btn.style.left = `${newX}px`;
                        btn.style.top = `${newY}px`;
                        btn.style.position = 'absolute';
                        btn.style.bottom = 'auto'; // Reset initial positioning
                    });
                    // Mobile touch logic (Make it possible but annoying)
                    btn.addEventListener('touchstart', (e) => {
                        if (Math.random() > 0.7) { // 30% chance to click it
                            success();
                        } else {
                            e.preventDefault(); // Prevent click
                            const parent = btn.parentElement;
                            const maxX = parent.clientWidth - btn.clientWidth - 20;
                            const maxY = parent.clientHeight - btn.clientHeight - 20;
                            btn.style.left = `${Math.random() * maxX}px`;
                            btn.style.top = `${Math.random() * maxY}px`;
                            btn.style.position = 'absolute';
                            btn.style.bottom = 'auto';
                        }
                    });
                    btn.addEventListener('click', success);
                }, 100);
            }
            // --- LEVEL 3: Confusing Colors (The Switcheroo) ---
            else if (level === 3) {
                container.innerHTML = `
                    <div class="bg-white p-8 rounded-2xl modal-shadow text-center">
                        <h3 class="text-xl font-bold text-slate-800 mb-4">Account Status</h3>
                        <div class="grid grid-cols-2 gap-4">
                            <button onclick="fail('You Cancelled the Cancellation!')" class="bg-emerald-500 hover:bg-emerald-600 text-white p-6 rounded-xl flex flex-col items-center gap-2 transition-transform active:scale-95 shadow-lg shadow-emerald-200">
                                <span class="text-3xl"><svg class="w-4 h-4 inline-block text-emerald-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg></span>
                                <span class="font-bold text-xs uppercase tracking-widest mt-2">Cancel Cancellation</span>
                            </button>
                            <button onclick="success()" class="bg-red-500 hover:bg-red-600 text-white p-6 rounded-xl flex flex-col items-center gap-2 transition-transform active:scale-95 shadow-lg shadow-red-200">
                                <span class="text-3xl"><svg class="w-4 h-4 inline-block text-rose-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></span>
                                <span class="font-bold text-xs uppercase tracking-widest mt-2">Confirm Cancellation</span>
                            </button>
                        </div>
                        <p class="text-[10px] text-slate-400 mt-6 italic bg-slate-50 p-2 rounded">
                            Tip: To stop the process of stopping your subscription, click the green checkmark.
                        </p>
                    </div>
                `;
            }
            // --- LEVEL 4: Trick Questions (Double Negatives) ---
            else if (level === 4) {
                container.innerHTML = `
                    <div class="bg-white p-8 rounded-2xl modal-shadow max-w-sm mx-auto">
                        <h3 class="text-lg font-bold text-slate-800 mb-4">Final Preferences</h3>
                        <div class="flex items-start gap-4 mb-8 bg-slate-50 p-5 rounded-xl border border-slate-200">
                            <input type="checkbox" id="trick-box" class="w-6 h-6 text-blue-600 mt-1 rounded focus:ring-blue-500 border-gray-300 cursor-pointer">
                            <label for="trick-box" class="text-sm text-slate-600 leading-snug cursor-pointer select-none">
                                Uncheck this box if you do <b class="text-slate-900">not</b> want to <b class="text-slate-900">not</b> stop receiving our newsletter updates indefinitely.
                            </label>
                        </div>
                        <button onclick="checkLevel4()" class="btn-primary w-full py-4 rounded-xl text-white font-bold shadow-md">
                            Continue
                        </button>
                    </div>
                `;
            }
            // --- LEVEL 5: The Fake Loader (Friction) ---
            else if (level === 5) {
                container.innerHTML = `
                    <div class="bg-white p-12 rounded-2xl modal-shadow text-center min-h-[300px] flex flex-col justify-center items-center relative">
                        <div id="loader-spinner" class="w-16 h-16 border-4 border-blue-100 border-t-blue-600 rounded-full animate-spin mb-6"></div>
                        <h3 id="loader-text" class="text-lg font-bold text-slate-800 mb-2">Processing Unsubscribe...</h3>
                        <p id="loader-sub" class="text-sm text-slate-500 animate-pulse">Do not close this window.</p>
                        <div id="fake-error" class="hidden w-full mt-4 animate-bounce-in">
                            <div class="bg-red-50 p-4 rounded-xl border border-red-100 mb-4">
                                <p class="text-red-600 font-bold text-sm mb-2"><svg class="w-4 h-4 inline-block text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg> Error 404: Subscription ID invalid.</p>
                                <button onclick="reloadLevel5()" class="bg-red-500 hover:bg-red-600 text-white px-4 py-3 rounded-lg text-sm font-bold w-full shadow-md transition-colors">
                                    Retry Connection
                                </button>
                            </div>
                            <button onclick="success()" class="text-[10px] text-slate-300 hover:text-slate-500 underline font-mono">
                                [DEV_MODE]: Force Quit Process
                            </button>
                        </div>
                    </div>
                `;
                // 4 seconds of fake loading time
                setTimeout(() => {
                    const spinner = document.getElementById('loader-spinner');
                    if (spinner) spinner.classList.add('hidden');
                    const text = document.getElementById('loader-text');
                    if (text) text.innerText = "Connection Failed";
                    const sub = document.getElementById('loader-sub');
                    if (sub) sub.innerText = "We couldn't verify your request at this time.";
                    const err = document.getElementById('fake-error');
                    if (err) err.classList.remove('hidden');
                }, 4000);
            }
        }
        function checkLevel4() {
            const box = document.getElementById('trick-box');
            // Logic: "Uncheck if you do NOT want to NOT stop"
            // "Not stop" = continue.
            // "Do not want to continue" = stop.
            // "Uncheck if you want to stop".
            // So if Unchecked (false) -> Stop (Success).
            // BUT wait... "receiving newsletter updates indefinitely".
            // Let's simplify the user experience of "Hell". Usually you HAVE to check something to leave.
            // Let's invert typical logic.
            // If they check it, they acknowledge the confusing text.
            // If they don't check it, they fail.
            // Actually, let's make it random logic based on pure confusion:
            // "Uncheck this box if you do not want to not stop..."
            // Double negative = "Uncheck if you want to stop".
            // So checked = stay?
            if (!box.checked) {
                success();
            } else {
                fail("You agreed to 'not stop' (continue)!");
            }
        }
        function reloadLevel5() {
            fail("It failed again! Look closer.");
            loadLevel(5);
        }
